alter table public.schoolpro_admissions add column if not exists enrollment_status text not null default 'not_enrolled',add column if not exists enrolled_at timestamptz;
create or replace function public.finalize_schoolpro_enrollment(p_application uuid) returns uuid language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions; sid uuid;begin select * into a from public.schoolpro_admissions where id=p_application for update;if a.id is null then raise exception 'Application not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','registrar','admissions_officer')) and not exists(select 1 from public.schoolpro_schools s where s.id=a.school_id and s.owner_id=auth.uid()) then raise exception 'Not authorized';end if;if not exists(select 1 from public.schoolpro_admission_acceptances x where x.application_id=a.id) then raise exception 'Admission offer has not been accepted';end if;sid:=public.admit_schoolpro_applicant(a.id);update public.schoolpro_admissions set enrollment_status='enrolled',enrolled_at=now() where id=a.id;return sid;end$$;revoke all on function public.finalize_schoolpro_enrollment(uuid) from public,anon;grant execute on function public.finalize_schoolpro_enrollment(uuid) to authenticated;
create or replace function public.create_schoolpro_portal_invite(p_student uuid,p_email text,p_type text) returns uuid language plpgsql security definer set search_path='' as $$declare st public.schoolpro_students; iid uuid;begin select * into st from public.schoolpro_students where id=p_student;if st.id is null then raise exception 'Student not found';end if;if p_type not in('student','parent') then raise exception 'Invalid invite type';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=st.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','registrar','admissions_officer')) and not exists(select 1 from public.schoolpro_schools s where s.id=st.school_id and s.owner_id=auth.uid()) then raise exception 'Not authorized';end if;insert into public.schoolpro_portal_invites(school_id,student_id,email,invite_type) values(st.school_id,st.id,lower(trim(p_email)),p_type) returning id into iid;perform public.queue_schoolpro_email(st.school_id,p_email,st.first_name||' '||st.last_name,'portal_invitation','Your SchoolPro portal invitation',jsonb_build_object('student_id',st.id,'invite_type',p_type));return iid;end$$;revoke all on function public.create_schoolpro_portal_invite(uuid,text,text) from public,anon;grant execute on function public.create_schoolpro_portal_invite(uuid,text,text) to authenticated;